#!/usr/bin/env python3
"""Collect only known synthetic UI screenshots generated by VisualTest."""
from pathlib import Path
import shutil

names = 'home memories detail editor profile calendar collections statistics settings backup pdf wishes anniversaries search storage trash dark dark-editor'.split()
root = Path('app/build/outputs/connected_android_test_additional_output')
target = Path('docs/screenshots/1.1.0')
for name in names:
    found = list(root.rglob(f'screenshots-110/{name}.png'))
    if not found:
        raise SystemExit(f'Missing visual test screenshot: {name}')
    target.mkdir(parents=True, exist_ok=True)
    shutil.copy2(found[0], target / f'{name}.png')
